// ── Capa 1: Conciliación EXACTA ────────────────────────────────────────────
// Lee el payload del Webhook (body). Match exacto = mismo monto + misma
// referencia; respaldo por mismo monto + misma fecha. Signos ya normalizados
// por la app (cobranza/abono +, pago/cargo −).

const src = $('Webhook').first().json;
const payload = src.body ?? src;

const internos = payload.registros_internos ?? [];
const bancarios = payload.movimientos_bancarios ?? [];

const cents = (m) => Math.round(Number(m) * 100);

// Referencia canonica. COPIA EXACTA de src/lib/normalizacion/referencia.ts y de
// la expresion de `ref_norm` (migraciones 0029 / 0042). Si las tres divergen, un
// par casa en SQL y no aqui —o al reves— y la diferencia es invisible.
//
// Ademas de mayusculas y quitar separadores, descarta un primer segmento hecho
// SOLO de letras: el mismo recibo llega como `WIN-S001-11618954` desde el ERP
// del cliente y como `S001-11618954` desde el banco. Solo se quita si lo que
// queda sigue teniendo letras Y digitos y al menos 6 caracteres utiles; por eso
// `SR11-02748951` no se toca (SR11 lleva digitos: no es un nombre de entidad).
const limpiarRef = (s) => s.toUpperCase().replace(/[^A-Z0-9]/g, '');
const normRef = (r) => {
  const s = String(r ?? '').trim();
  if (s === '') return '';
  const resto = s.replace(/^[A-Za-z]+[-_/ ]+/, '');
  if (resto !== s && /[A-Za-z]/.test(resto) && /[0-9]/.test(resto)
      && limpiarRef(resto).length >= 6) {
    return limpiarRef(resto);
  }
  return limpiarRef(s);
};

const idxPorRef = new Map();
const idxPorFecha = new Map();
const push = (map, k, v) => {
  if (!map.has(k)) map.set(k, []);
  map.get(k).push(v);
};
bancarios.forEach((b, j) => {
  const c = cents(b.monto);
  const ref = normRef(b.referencia_banco);
  if (ref) push(idxPorRef, `${c}|${ref}`, j);
  push(idxPorFecha, `${c}|${b.fecha}`, j);
});

const bancUsado = new Set();
const intUsado = new Set();
const matches = [];

const tomarLibre = (lista, filtro) => {
  if (!lista) return -1;
  for (const j of lista) if (!bancUsado.has(j) && (!filtro || filtro(j))) return j;
  return -1;
};
const registrar = (i, j) => {
  intUsado.add(i);
  bancUsado.add(j);
  matches.push({
    ids_internos: [internos[i].id_interno],
    ids_movimientos: [bancarios[j].id_movimiento],
    metodo: 'exacta',
    confianza: null,
    diferencia_monto: 0,
    categoria_diferencia: null,
    justificacion: null,
    estado_revision: 'auto',
  });
};

// Pass 1: monto + referencia (ID de pago)
internos.forEach((it, i) => {
  const ref = normRef(it.referencia);
  if (!ref) return;
  const j = tomarLibre(idxPorRef.get(`${cents(it.monto)}|${ref}`));
  if (j !== -1) registrar(i, j);
});
// Pass 2: monto + fecha.
//
// ⚠️ NUNCA contra una referencia que se contradice. Este respaldo existe para
// datos SIN referencia (ventas al contado, extractos que no la traen). Cuando
// los dos lados SÍ la traen y no coinciden, son operaciones distintas: casarlas
// por monto+fecha es una loteria.
//
// A escala esto no es teorico. En una recaudadora de 20.000 movimientos hay
// cientos de recibos de S/ 99 el mismo dia: el pass 2 emparejo 541 pares con
// codigos de operacion que no tenian nada que ver, y los marco `auto` — o sea,
// conciliados sin que nadie los mirara. Peor aun, cada match falso se lleva el
// movimiento que le tocaba al recibo legitimo, dejandolo huerfano: el error se
// propaga y acaba inflando el descuadre del periodo.
const compatiblePorRef = (i, j) => {
  const a = normRef(internos[i].referencia);
  const b = normRef(bancarios[j].referencia_banco);
  return !a || !b || a === b; // si a alguno le falta, no hay contradiccion
};

internos.forEach((it, i) => {
  if (intUsado.has(i)) return;
  const j = tomarLibre(
    idxPorFecha.get(`${cents(it.monto)}|${it.fecha}`),
    (cand) => compatiblePorRef(i, cand),
  );
  if (j !== -1) registrar(i, j);
});

return [{
  json: {
    job_id: payload.job_id,
    metadata: payload.metadata,
    config: payload.config,
    total_internos: internos.length,
    total_bancarios: bancarios.length,
    matches,
    pendientes_internos: internos.filter((_, i) => !intUsado.has(i)),
    pendientes_bancarios: bancarios.filter((_, j) => !bancUsado.has(j)),
  },
}];

// ── Capa 2: Conciliación DIFUSA (tolerancias + coincidencia de nombre) ─────
// Toma los pendientes de la capa exacta y concilia por cercanía de monto y
// fecha, EXIGIENDO además al menos una palabra en común entre la contraparte
// (interno) y la glosa (banco). Diferencia de monto tolerada =
// max(tolerancia_monto_abs, |monto|*pct). Fecha tolerada = tolerancia_dias.

const prev = $json;
const { job_id, metadata, config, total_internos, total_bancarios } = prev;
const matches = [...prev.matches];
const internos = prev.pendientes_internos ?? [];
const bancarios = prev.pendientes_bancarios ?? [];

const tolAbs = Number(config?.tolerancia_monto_abs ?? 0);
const tolPct = Number(config?.tolerancia_monto_pct ?? 0);
const tolDias = Number(config?.tolerancia_dias ?? 0);

const dias = (a, b) => Math.abs((Date.parse(a) - Date.parse(b)) / 86400000);

// Tokenizador: MAYÚSCULAS sin acentos, palabras de >=3 letras, sin términos
// bancarios genéricos.
const STOP = new Set([
  "DEPOSITO", "TRANSFERENCIA", "TRANSF", "TRANSFER", "RECIBIDA", "RECIBIDO",
  "ENVIADA", "ENVIADO", "PAGO", "PAGOS", "ABONO", "CARGO", "CUOTA",
  "REPETICION", "DEVOLUCION", "CCE", "INTERBANCARIA", "INTERBANCARIO",
  "OPERACION", "NRO", "REF", "REFERENCIA", "FACTURA", "BOLETA", "SAC", "EIRL",
  "SRL", "DEL", "LOS", "LAS", "POR", "CON",
  "EFECTIVO", "MENSUALIDAD", "MATRICULA", "PENSION", "INSCRIPCION",
  "ENERO", "FEBRERO", "MARZO", "ABRIL", "MAYO", "JUNIO", "JULIO", "AGOSTO",
  "SEPTIEMBRE", "SETIEMBRE", "OCTUBRE", "NOVIEMBRE", "DICIEMBRE",
]);
const palabras = (t) =>
  String(t ?? "")
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toUpperCase()
    .split(/[^A-Z0-9]+/)
    .filter((w) => w.length >= 3 && !STOP.has(w));
const comunesEntre = (a, b) => {
  const setB = new Set(palabras(b));
  return [...new Set(palabras(a).filter((w) => setB.has(w)))];
};

const bancUsado = new Set();
const intUsado = new Set();

// ── Precálculo: lo que no depende del par, fuera del bucle ────────────────
// Antes `comunesEntre` tokenizaba la MISMA glosa una vez por cada registro
// interno: con 20.000 x 20.000 eso son 400 millones de `normalize` + regex +
// Set, y el runner de n8n aborta a los 30 segundos ("runner became
// unresponsive"). Ahora cada glosa se tokeniza UNA vez.
const bancPrep = bancarios.map((bc) => ({
  bc,
  t: Date.parse(bc.fecha),
  pal: new Set(palabras(bc.glosa)),
}));

// Índice por monto redondeado a soles. La tolerancia acota la banda, así que
// solo hay que mirar unos pocos cubos en vez de los 20.000 movimientos.
const cubos = new Map();
bancPrep.forEach((b, j) => {
  const k = Math.round(b.bc.monto);
  if (!cubos.has(k)) cubos.set(k, []);
  cubos.get(k).push(j);
});

const MS_DIA = 86400000;

internos.forEach((it, i) => {
  const tol = Math.max(tolAbs, Math.abs(it.monto) * (tolPct / 100));
  const tIt = Date.parse(it.fecha);
  const palIt = palabras(it.contraparte);
  if (palIt.length === 0) return; // sin nombre no hay match difuso posible

  // Candidatos por banda de monto. Se ordenan por índice para conservar el
  // mismo emparejamiento que el recorrido secuencial original: gana el
  // movimiento más antiguo de la lista, no el del cubo que toque antes.
  const desde = Math.round(it.monto - tol) - 1;
  const hasta = Math.round(it.monto + tol) + 1;
  const candidatos = [];
  for (let k = desde; k <= hasta; k++) {
    const lista = cubos.get(k);
    if (lista) for (const j of lista) if (!bancUsado.has(j)) candidatos.push(j);
  }
  candidatos.sort((a, b) => a - b);

  for (const j of candidatos) {
    const { bc, t, pal } = bancPrep[j];
    if (Math.sign(it.monto) !== Math.sign(bc.monto)) continue;
    const dif = Number((it.monto - bc.monto).toFixed(2));
    if (Math.abs(dif) > tol) continue;
    if (Math.abs((tIt - t) / MS_DIA) > tolDias) continue;
    const comunes = [...new Set(palIt.filter((w) => pal.has(w)))];
    if (comunes.length === 0) continue; // exige coincidencia de nombre
    matches.push({
      ids_internos: [it.id_interno],
      ids_movimientos: [bc.id_movimiento],
      metodo: 'difusa',
      confianza: null,
      diferencia_monto: dif,
      categoria_diferencia: Math.abs(dif) > 0 ? 'comision_bancaria' : null,
      justificacion:
        Math.abs(dif) > 0
          ? `Coincidencia por nombre (${comunes.join(', ')}); diferencia de ${dif.toFixed(2)} compatible con comisión bancaria.`
          : `Coincidencia por nombre (${comunes.join(', ')}).`,
      estado_revision: 'auto',
    });
    intUsado.add(i);
    bancUsado.add(j);
    break;
  }
});

return [{
  json: {
    job_id,
    metadata,
    config,
    total_internos,
    total_bancarios,
    matches,
    pendientes_internos: internos.filter((_, i) => !intUsado.has(i)),
    pendientes_bancarios: bancarios.filter((_, j) => !bancUsado.has(j)),
  },
}];

// ── Capa 2.5: AGRUPACIÓN 1:N / N:1 (subset-sum) ────────────────────────────
// Un depósito bancario que agrupa varios pagos internos (o un pago dividido en
// varios movimientos). Se acota fuerte para precisión: COINCIDENCIA DE NOMBRE
// OBLIGATORIA (cada miembro comparte >=1 palabra con el objetivo), suma casi
// EXACTA, grupo pequeño (<= max_combinacion), en ventana de fecha. Se proponen
// como SUGERENCIAS (estado 'pendiente') para revisión humana. Va entre Difusa y
// la capa de IA.

const prev = $json;
const { job_id, metadata, config, total_internos, total_bancarios } = prev;
const matches = [...prev.matches];
const internos = prev.pendientes_internos ?? [];
const bancarios = prev.pendientes_bancarios ?? [];

const tolSum = Math.min(Number(config?.tolerancia_monto_abs ?? 5), 0.5);
const ventana = Number(config?.ventana_ia_dias ?? 30);
const maxTam = Number(config?.max_combinacion ?? 3);

const STOP = new Set([
  "DEPOSITO", "TRANSFERENCIA", "TRANSF", "TRANSFER", "RECIBIDA", "RECIBIDO",
  "ENVIADA", "ENVIADO", "PAGO", "PAGOS", "ABONO", "CARGO", "CUOTA",
  "REPETICION", "DEVOLUCION", "CCE", "INTERBANCARIA", "INTERBANCARIO",
  "OPERACION", "NRO", "REF", "REFERENCIA", "FACTURA", "BOLETA", "SAC", "EIRL",
  "SRL", "DEL", "LOS", "LAS", "POR", "CON",
  "EFECTIVO", "MENSUALIDAD", "MATRICULA", "PENSION", "INSCRIPCION",
  "ENERO", "FEBRERO", "MARZO", "ABRIL", "MAYO", "JUNIO", "JULIO", "AGOSTO",
  "SEPTIEMBRE", "SETIEMBRE", "OCTUBRE", "NOVIEMBRE", "DICIEMBRE",
]);
const palabras = (t) =>
  String(t ?? "").normalize("NFD").replace(/[̀-ͯ]/g, "").toUpperCase()
    .split(/[^A-Z0-9]+/).filter((w) => w.length >= 3 && !STOP.has(w));
const comunesEntre = (a, b) => {
  const B = new Set(palabras(b));
  return palabras(a).filter((w) => B.has(w));
};
// Referencia normalizada, igual que en la capa exacta: si dos partidas traen el
// MISMO codigo de operacion, esa es una identidad mas fuerte que un nombre.
// COPIA EXACTA de 01_exacta.js / src/lib/normalizacion/referencia.ts / ref_norm.
// Descarta un primer segmento de solo letras (`WIN-S001-11618954` ->
// `S001-11618954`) cuando lo que queda sigue teniendo letras, digitos y >= 6
// caracteres utiles; `SR11-02748951` no se toca.
const limpiarRef = (s) => s.toUpperCase().replace(/[^A-Z0-9]/g, "");
const normRef = (r) => {
  const s = String(r ?? "").trim();
  if (s === "") return "";
  const resto = s.replace(/^[A-Za-z]+[-_/ ]+/, "");
  if (resto !== s && /[A-Za-z]/.test(resto) && /[0-9]/.test(resto)
      && limpiarRef(resto).length >= 6) {
    return limpiarRef(resto);
  }
  return limpiarRef(s);
};
const compartenPalabra = (a, b) => { for (const w of a) if (b.has(w)) return true; return false; };
// Sobre timestamps YA parseados. La version anterior recibia cadenas y llamaba
// a Date.parse dos veces POR PAR: con 4.382 x 3.204 pendientes son 28 millones
// de parseos, y el runner de n8n aborta por inactividad a los 30 s. Mismo
// defecto que tenia 02_difusa.js.
const diasTs = (a, b) => Math.abs((a - b) / 86400000);

function* combinaciones(items, maxT) {
  const n = items.length;
  function* rec(inicio, acc) {
    if (acc.length >= 2) yield acc.slice();
    if (acc.length >= maxT) return;
    for (let i = inicio; i < n; i++) { acc.push(items[i]); yield* rec(i + 1, acc); acc.pop(); }
  }
  yield* rec(0, []);
}

function agrupar(unos, muchos) {
  const usados = new Set();
  const grupos = [];

  // Indices del prefiltro. El candidato tiene que compartir la REFERENCIA o al
  // menos una palabra, asi que no hace falta recorrer los otros: se buscan.
  // Sin esto cada objetivo recorria los miles de candidatos enteros.
  //
  // No cambia la semantica: el conjunto que sale de los indices es exactamente
  // el que pasaba el prefiltro. Lo que cambia es cuantos se miran para
  // encontrarlo.
  const porRef = new Map();
  const porPalabra = new Map();
  muchos.forEach((m, i) => {
    m.i = i; // posicion original, para reproducir el orden de antes
    if (m.ref) {
      if (!porRef.has(m.ref)) porRef.set(m.ref, []);
      porRef.get(m.ref).push(m);
    }
    for (const w of m.pal) {
      if (!porPalabra.has(w)) porPalabra.set(w, []);
      porPalabra.get(w).push(m);
    }
  });

  for (const t of unos) {
    // Prefiltro de identidad: cada candidato debe compartir con el objetivo la
    // REFERENCIA o al menos una palabra del nombre. Sin prefiltro, un subset-sum
    // agrupa partidas sin relacion cuya suma cuadra por casualidad.
    //
    // La referencia se acepta ademas del nombre porque hay operaciones donde la
    // identidad no esta en el nombre: en una cuenta recaudadora los recibos
    // llegan sin contraparte y lo que comparten los que se pagaron juntos es el
    // codigo de operacion. Exigir nombre alli hacia imposible la agrupacion — y
    // eran justo los casos 1:N que hay que conciliar. Es el mismo criterio que
    // ya usa ia_llm_01_candidatos.js, donde compartir referencia basta.
    const vistos = new Set();
    const posibles = [];
    const juntar = (lista) => {
      if (!lista) return;
      for (const m of lista) {
        if (vistos.has(m.i)) continue;
        vistos.add(m.i);
        posibles.push(m);
      }
    };
    if (t.ref) juntar(porRef.get(t.ref));
    for (const w of t.pal) juntar(porPalabra.get(w));

    const cands = posibles
      .filter((m) => !usados.has(m.id) && Math.sign(m.monto) === Math.sign(t.monto) &&
        Math.abs(m.monto) <= Math.abs(t.monto) + tolSum && diasTs(t.ts, m.ts) <= ventana)
      // Por posicion original primero: asi el orden de empate es el mismo que
      // cuando se recorria la lista entera, y el resultado no cambia.
      .sort((a, b) => a.i - b.i)
      .sort((a, b) => diasTs(t.ts, a.ts) - diasTs(t.ts, b.ts))
      .slice(0, 12);
    if (cands.length < 2) continue;
    let mejor = null;
    for (const combo of combinaciones(cands, maxTam)) {
      const suma = combo.reduce((s, x) => s + x.monto, 0);
      if (Math.abs(suma - t.monto) > tolSum) continue;
      const dif = Number((suma - t.monto).toFixed(2));
      // Todos los miembros ya comparten identidad (referencia o nombre):
      // preferir menos elementos y, a igualdad, menor diferencia de monto.
      if (!mejor || combo.length < mejor.combo.length ||
          (combo.length === mejor.combo.length && Math.abs(dif) < Math.abs(mejor.dif))) {
        mejor = { combo, dif };
      }
    }
    if (!mejor) continue;
    grupos.push({ targetId: t.id, ids: mejor.combo.map((x) => x.id), dif: mejor.dif,
                  n: mejor.combo.length,
                  porRef: Boolean(t.ref) && mejor.combo.every((x) => x.ref === t.ref) });
    for (const x of mejor.combo) usados.add(x.id);
  }
  return grupos;
}

// Los tokens y la referencia se calculan UNA vez por partida, no dentro del
// bucle: con miles de pendientes, re-tokenizar por cada par tumba el runner de
// n8n por inactividad (mismo fallo que tenia 02_difusa.js).
const itemInt = (r) => {
  const texto = r.contraparte ?? r.descripcion ?? null;
  return { id: r.id_interno, monto: r.monto, fecha: r.fecha, texto, ts: Date.parse(r.fecha),
           pal: new Set(palabras(texto)), ref: normRef(r.referencia) };
};
const itemBanc = (m) => {
  const texto = m.glosa ?? null;
  return { id: m.id_movimiento, monto: m.monto, fecha: m.fecha, texto, ts: Date.parse(m.fecha),
           pal: new Set(palabras(texto)), ref: normRef(m.referencia_banco) };
};

const usadoInt = new Set();
const usadoBanc = new Set();

// 1 banco : N internos
for (const g of agrupar(bancarios.filter((m) => !usadoBanc.has(m.id_movimiento)).map(itemBanc),
                        internos.filter((r) => !usadoInt.has(r.id_interno)).map(itemInt))) {
  matches.push({
    ids_internos: g.ids, ids_movimientos: [g.targetId], metodo: "ia", confianza: null,
    diferencia_monto: g.dif, categoria_diferencia: "agrupacion_1aN",
    justificacion: `Agrupación: ${g.n} registros internos suman el depósito (dif. ${g.dif}).${g.porRef ? " Comparten el mismo código de operación." : ""}`,
    estado_revision: "pendiente",
  });
  usadoBanc.add(g.targetId);
  for (const id of g.ids) usadoInt.add(id);
}
// 1 interno : N bancos
for (const g of agrupar(internos.filter((r) => !usadoInt.has(r.id_interno)).map(itemInt),
                        bancarios.filter((m) => !usadoBanc.has(m.id_movimiento)).map(itemBanc))) {
  matches.push({
    ids_internos: [g.targetId], ids_movimientos: g.ids, metodo: "ia", confianza: null,
    diferencia_monto: -g.dif, categoria_diferencia: "agrupacion_1aN",
    justificacion: `Agrupación: el pago se refleja en ${g.n} movimientos bancarios (dif. ${-g.dif}).${g.porRef ? " Comparten el mismo código de operación." : ""}`,
    estado_revision: "pendiente",
  });
  usadoInt.add(g.targetId);
  for (const id of g.ids) usadoBanc.add(id);
}

return [{
  json: {
    job_id, metadata, config, total_internos, total_bancarios, matches,
    pendientes_internos: internos.filter((r) => !usadoInt.has(r.id_interno)),
    pendientes_bancarios: bancarios.filter((m) => !usadoBanc.has(m.id_movimiento)),
  },
}];

// ── Capa 3: IA sobre CANDIDATOS (ruta heurística, sin LLM) ─────────────────
// Etapa de preparación de candidatos (blocking + features + score + top-K) y
// luego adjudicación: toma el mejor candidato por score de forma greedy.
// (La ruta con LLM real vive en workflow_conciliacion_ia.json.)

const prev = $json;
const { job_id, metadata, config, total_internos, total_bancarios } = prev;
const matches = [...prev.matches];
const internos = prev.pendientes_internos ?? [];
const bancarios = prev.pendientes_bancarios ?? [];

const tolIa = Number(config?.tolerancia_ia_monto ?? 10);
const umbral = Number(config?.umbral_confianza_auto ?? 0.95);
const topK = Number(config?.top_k_candidatos ?? 3);
const ventanaIa = Number(config?.ventana_ia_dias ?? 30);

// ── Utilidades de matching ────────────────────────────────────────────────
const STOP = new Set([
  "DEPOSITO", "TRANSFERENCIA", "TRANSF", "TRANSFER", "RECIBIDA", "RECIBIDO",
  "ENVIADA", "ENVIADO", "PAGO", "PAGOS", "ABONO", "CARGO", "CUOTA",
  "REPETICION", "DEVOLUCION", "CCE", "INTERBANCARIA", "INTERBANCARIO",
  "OPERACION", "NRO", "REF", "REFERENCIA", "FACTURA", "BOLETA", "SAC", "EIRL",
  "SRL", "DEL", "LOS", "LAS", "POR", "CON",
  "EFECTIVO", "MENSUALIDAD", "MATRICULA", "PENSION", "INSCRIPCION",
  "ENERO", "FEBRERO", "MARZO", "ABRIL", "MAYO", "JUNIO", "JULIO", "AGOSTO",
  "SEPTIEMBRE", "SETIEMBRE", "OCTUBRE", "NOVIEMBRE", "DICIEMBRE",
]);
const palabras = (t) =>
  String(t ?? "").normalize("NFD").replace(/[̀-ͯ]/g, "").toUpperCase()
    .split(/[^A-Z0-9]+/).filter((w) => w.length >= 3 && !STOP.has(w));
const comunesEntre = (a, b) => {
  const B = new Set(palabras(b));
  return [...new Set(palabras(a).filter((w) => B.has(w)))];
};
const jaccard = (a, b) => {
  const A = new Set(palabras(a)), B = new Set(palabras(b));
  if (!A.size && !B.size) return 0;
  let i = 0; for (const t of A) if (B.has(t)) i++;
  const u = new Set([...A, ...B]).size; return u ? i / u : 0;
};
// Referencias: token alfanumérico con >=1 letra y >=1 dígito, longitud >=4.
// Se extraen del campo de referencia y del texto libre (glosa/descripción).
const esRefToken = (t) => t.length >= 4 && /[A-Z]/.test(t) && /[0-9]/.test(t);
const refsDeTexto = (texto, set) => {
  for (const tok of String(texto ?? "").toUpperCase().split(/[^A-Z0-9]+/)) if (esRefToken(tok)) set.add(tok);
};
// Forma canonica de la referencia: la misma de 01_exacta.js / ref_norm. Se
// aniade ADEMAS de la cruda, nunca en su lugar: asi ningun candidato que antes
// aparecia deja de aparecer, y los `WIN-S001-...` del ERP alcanzan a los
// `S001-...` del banco.
const limpiarRef = (s) => s.toUpperCase().replace(/[^A-Z0-9]/g, "");
const canonRef = (r) => {
  const s = String(r ?? "").trim();
  if (s === "") return "";
  const resto = s.replace(/^[A-Za-z]+[-_/ ]+/, "");
  if (resto !== s && /[A-Za-z]/.test(resto) && /[0-9]/.test(resto)
      && limpiarRef(resto).length >= 6) {
    return limpiarRef(resto);
  }
  return limpiarRef(s);
};
// ⚠️⚠️ El CAMPO de referencia es una referencia POR DEFINICION: el usuario lo
// dijo al mapear esa columna. `esRefToken` exige una letra y un digito —bien
// para extraer codigos de un texto libre, donde un numero suelto puede ser un
// importe o una fecha— pero aplicado al campo descarta los codigos de operacion
// PERUANOS, que son puramente numericos (30010182).
//
// Con eso, `comparteRef` no se cumplia nunca y la etapa de candidatos perdia su
// unico vinculo fuerte: toda retencion, detraccion o percepcion —que comparte
// codigo con su movimiento y solo difiere en el importe— quedaba fuera de la
// banda de monto y jamas llegaba al modelo. En una prueba de 233 x 221 el LLM
// recibio CERO shortlists y contesto, con razon, que no habia ningun par.
const esRefCampo = (t) => t.length >= 4;
const refCampo = (ref, set) => {
  const c = limpiarRef(String(ref ?? "")); if (esRefCampo(c)) set.add(c);
  const k = canonRef(ref); if (k !== c && esRefCampo(k)) set.add(k);
};
const refsInterno = (it) => { const s = new Set(); refCampo(it.referencia, s); refsDeTexto(it.descripcion, s); return s; };
const refsBanco = (bc) => { const s = new Set(); refCampo(bc.referencia_banco, s); refsDeTexto(bc.glosa, s); return s; };
const intersecta = (a, b) => { for (const x of a) if (b.has(x)) return true; return false; };
const dias = (a, b) => Math.abs((Date.parse(a) - Date.parse(b)) / 86400000);
const catProb = (d) =>
  d < 0.005 ? "diferencia_temporal" : d <= 10 ? "comision_bancaria" : "requiere_investigacion";

function generarCandidatos(ints, bancs, tolIaMonto, ventana, K) {
  const out = [];
  const refsBc = bancs.map((bc) => refsBanco(bc));
  for (const it of ints) {
    const refsIt = refsInterno(it);
    const cands = [];
    for (let bi = 0; bi < bancs.length; bi++) {
      const bc = bancs[bi];
      if (Math.sign(it.monto) !== Math.sign(bc.monto)) continue;
      const d = dias(it.fecha, bc.fecha);
      if (d > ventana) continue;
      const difAbs = Math.abs(it.monto - bc.monto);
      const comparteRef = intersecta(refsIt, refsBc[bi]);
      const comunes = comunesEntre(it.contraparte, bc.glosa);
      // Si comparte referencia, es candidato aunque no comparta nombre ni esté
      // en la banda de monto. Si no, exige nombre Y banda de monto.
      if (!comparteRef) {
        if (!comunes.length) continue;
        if (difAbs > tolIaMonto) continue;
      }
      const sim = jaccard(it.contraparte, bc.glosa);
      const cercM = 1 - Math.min(difAbs / (tolIaMonto || 1), 1);
      const cercF = 1 - Math.min(d / (ventana || 1), 1);
      const score = Number(Math.min(1, 0.5 * sim + 0.3 * cercM + 0.2 * cercF + (comparteRef ? 0.4 : 0)).toFixed(3));
      cands.push({
        id_movimiento: bc.id_movimiento,
        dif: Number((it.monto - bc.monto).toFixed(2)),
        dif_abs: Number(difAbs.toFixed(2)),
        dias: d,
        palabras_comunes: comunes,
        score,
        categoria_probable: catProb(difAbs),
      });
    }
    cands.sort((a, b) => b.score - a.score);
    if (cands.length) out.push({ id_interno: it.id_interno, candidatos: cands.slice(0, K) });
  }
  return out;
}

// ── Adjudicación greedy por score ─────────────────────────────────────────
const shortlists = generarCandidatos(internos, bancarios, tolIa, ventanaIa, topK);
const idxInt = new Map(internos.map((r, i) => [r.id_interno, i]));
const idxBanc = new Map(bancarios.map((m, j) => [m.id_movimiento, j]));
const intUsado = new Set();
const bancUsado = new Set();

const propuestas = shortlists
  .map((s) => ({ id: s.id_interno, best: s.candidatos[0] }))
  .filter((p) => p.best && p.best.score >= 0.4)
  .sort((a, b) => b.best.score - a.best.score);

for (const p of propuestas) {
  const i = idxInt.get(p.id);
  const j = idxBanc.get(p.best.id_movimiento);
  if (i == null || j == null || intUsado.has(i) || bancUsado.has(j)) continue;
  const it = internos[i], bc = bancarios[j];
  const confianza = Math.min(0.94, Math.max(0.6, p.best.score));
  matches.push({
    ids_internos: [it.id_interno],
    ids_movimientos: [bc.id_movimiento],
    metodo: "ia",
    confianza,
    diferencia_monto: p.best.dif,
    categoria_diferencia: p.best.categoria_probable,
    justificacion: `Candidato IA: nombre (${p.best.palabras_comunes.join(", ")}), dif. ${p.best.dif_abs}, ${p.best.dias} día(s) (score ${p.best.score}).`,
    estado_revision: confianza >= umbral ? "auto" : "pendiente",
  });
  intUsado.add(i);
  bancUsado.add(j);
}

return [{
  json: {
    job_id, metadata, config, total_internos, total_bancarios, matches,
    pendientes_internos: internos.filter((_, i) => !intUsado.has(i)),
    pendientes_bancarios: bancarios.filter((_, j) => !bancUsado.has(j)),
  },
}];

// ── Ensamblar RESULTADO (§7.3) + cuadre de saldos ──────────────────────────
// Junta todos los matches, arma resumen y no_conciliados desde los pendientes,
// y calcula el cuadre bancario a partir de los saldos. Devuelve el cuerpo listo
// para el UPDATE a Supabase (un solo campo JSONB `resultado`).

const prev = $json;
const { job_id, metadata, total_internos, total_bancarios } = prev;
const matches = prev.matches ?? [];
const pendInt = prev.pendientes_internos ?? [];
const pendBanc = prev.pendientes_bancarios ?? [];

const cuenta = (m) => matches.filter((x) => x.metodo === m).length;

const no_conciliados = [
  ...pendInt.map((it) => ({
    id: it.id_interno,
    lado: 'interno',
    categoria: 'requiere_investigacion',
    sugerencia: it.monto >= 0 ? 'Posible depósito en tránsito' : 'Posible cheque no cobrado',
  })),
  ...pendBanc.map((bc) => ({
    id: bc.id_movimiento,
    lado: 'bancario',
    categoria: 'ajuste_requerido',
    sugerencia: 'Cargo/abono no registrado en libros',
  })),
];

// Cuadre bancario.
const saldos = metadata?.saldos ?? {};
const r2 = (n) => Number(Number(n).toFixed(2));
const saldoExtractoFinal = Number(saldos.saldo_extracto_final ?? 0);
// Pendientes de LIBROS: el extracto todavía no los refleja, así que se SUMAN
// (van con su signo: los cheques son negativos y por tanto restan).
const depositosEnTransito = pendInt.reduce((a, it) => a + (it.monto > 0 ? it.monto : 0), 0);
const chequesNoCobrados = pendInt.reduce((a, it) => a + (it.monto < 0 ? it.monto : 0), 0);
// Pendientes del BANCO: el extracto YA los incluye y los libros no, así que se
// RESTAN. Los dos signos, no solo uno.
//
// ⚠️ Aquí había dos fallos que se tapaban entre sí. Los abonos (`monto > 0`) no
// se contaban en ningún renglón: 24 depósitos de una recaudadora se evaporaron
// del informe. Y los cargos se SUMABAN en vez de restarse, que con una comisión
// de −50 no la corregía sino que la duplicaba con el signo cambiado (−100).
// El efecto conjunto: el cuadre no podía cerrar aunque toda diferencia
// estuviera explicada, que es justo lo que el cuadre existe para demostrar.
const abonosNoRegistrados = pendBanc.reduce((a, bc) => a + (bc.monto > 0 ? bc.monto : 0), 0);
const cargosNoRegistrados = pendBanc.reduce((a, bc) => a + (bc.monto < 0 ? bc.monto : 0), 0);
// ⚠️ Las diferencias DENTRO de un par emparejado tambien son partidas
// conciliatorias. Un comprobante de 100 casado con un deposito de 80 deja 20
// sin explicar: los libros dicen 100 y el banco 80, y ninguno de los dos esta
// "pendiente", asi que ese hueco se escapaba del cuadre.
//
// Con la capa exacta siempre es cero —casa por importe identico— y por eso no
// se notaba. La difusa, la IA y la agrupacion si producen pares con diferencia.
// Medido con junio completo: un solo par de la IA con 20 soles hacia que el
// cuadre no cuadrara contra la resta de los dos lados.
const difEmparejadas = matches.reduce((a, m) => a + Number(m.diferencia_monto ?? 0), 0);
const saldoBancoAjustado =
  saldoExtractoFinal +
  depositosEnTransito +
  chequesNoCobrados -
  abonosNoRegistrados -
  cargosNoRegistrados +
  difEmparejadas;
const saldoLibros = Number(saldos.saldo_libros_final ?? 0);

const resultado = {
  resumen: {
    total_internos,
    total_bancarios,
    conciliados_exactos: cuenta('exacta'),
    conciliados_difusos: cuenta('difusa'),
    sugeridos_ia: cuenta('ia'),
    sin_conciliar_internos: pendInt.length,
    sin_conciliar_bancarios: pendBanc.length,
  },
  matches,
  no_conciliados,
  cuadre: {
    saldo_extracto_final: r2(saldoExtractoFinal),
    depositos_en_transito: r2(depositosEnTransito),
    cheques_no_cobrados: r2(chequesNoCobrados),
    abonos_no_registrados: r2(abonosNoRegistrados),
    diferencias_emparejadas: r2(difEmparejadas),
    cargos_no_registrados: r2(cargosNoRegistrados),
    saldo_banco_ajustado: r2(saldoBancoAjustado),
    saldo_libros_final: r2(saldoLibros),
    diferencia: r2(saldoBancoAjustado - saldoLibros),
  },
};

return [{
  json: {
    job_id,
    resultado_update: {
      estado: 'completado',
      fase_actual: 'ia',
      resultado,
      completed_at: new Date().toISOString(),
    },
  },
}];
